package com.procurement.approvalrule.controller;
import com.procurement.approvalrule.dto.request.*; import com.procurement.approvalrule.dto.response.*; import com.procurement.approvalrule.service.*; import com.procurement.common.response.*; import jakarta.validation.Valid; import org.springframework.data.domain.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/approval-rules") public class ApprovalRuleController { private final ApprovalRuleService service; public ApprovalRuleController(ApprovalRuleService s){service=s;} private Pageable page(int page,int size,String sort,String direction){return PageRequest.of(page,size,Sort.by(Sort.Direction.fromString(direction),sort));} @PostMapping public ResponseEntity<ApiResponse<ApprovalRuleResponse>> create(@Valid @RequestBody ApprovalRuleRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(ApiResponse.success("Approval rule created",service.create(r)));} @GetMapping public ApiResponse<PageResponse<ApprovalRuleResponse>> search(@RequestParam(required=false)String keyword,@RequestParam(required=false)Long departmentId,@RequestParam(required=false)Boolean active,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size,@RequestParam(defaultValue="createdAt")String sort,@RequestParam(defaultValue="desc")String direction){return ApiResponse.success(service.search(keyword,departmentId,active,page(page,size,sort,direction)));} @GetMapping("/{id}") public ApiResponse<ApprovalRuleResponse> get(@PathVariable Long id){return ApiResponse.success(service.getById(id));} @PutMapping("/{id}") public ApiResponse<ApprovalRuleResponse> update(@PathVariable Long id,@Valid @RequestBody ApprovalRuleRequest r){return ApiResponse.success("Approval rule updated",service.update(id,r));} @DeleteMapping("/{id}") public ResponseEntity<Void> delete(@PathVariable Long id){service.delete(id);return ResponseEntity.noContent().build();} }
